def _embedded_template_zip_bytes() -> bytes:
    return zlib.decompress(base64.b85decode(_EMBEDDED_AXION_TEMPLATE_B85.encode('ascii')))

# ---- load the validated Luminator renderer ---------------------------------
def _load_renderer():
    # Normal/PyInstaller path: import the validated renderer as a bundled module.
    try:
        import luminator_ips_export as mod
        return mod
    except ImportError:
        pass
    # Development fallback: load the sibling source file directly.
    here = Path(__file__).resolve().parent
    p = here / 'luminator_ips_export.py'
    if not p.exists():
        raise FileNotFoundError('luminator_ips_export.py is required (or must be bundled into the EXE)')
    name='_luminator_ips_export_core'
    spec=importlib.util.spec_from_file_location(name,p)
    mod=importlib.util.module_from_spec(spec); sys.modules[name]=mod
    assert spec and spec.loader
    spec.loader.exec_module(mod)
    return mod

# ---- minimal dBase III reader/writer --------------------------------------
@dataclass
class DbfField:
    name:str; typ:str; length:int; decimals:int; descriptor:bytes

class DbfTemplate:
    def __init__(self,path:Path):
        self.path=path; self.raw=bytearray(path.read_bytes())
        if len(self.raw)<33 or self.raw[0] not in (0x03,0x83):
            raise ValueError(f'Unsupported DBF: {path}')
        self.header_len=int.from_bytes(self.raw[8:10],'little')
        self.record_len=int.from_bytes(self.raw[10:12],'little')
        self.fields=[]; o=32
        while o<self.header_len and self.raw[o]!=0x0D:
            d=bytes(self.raw[o:o+32]); name=d[:11].split(b'\0',1)[0].decode('latin1')
            self.fields.append(DbfField(name,chr(d[11]),d[16],d[17],d)); o+=32
        self.header=bytearray(self.raw[:self.header_len])
        self.n_records=int.from_bytes(self.raw[4:8],'little')

    def _format(self,f:DbfField,v:Any)->bytes:
        n=f.length
        if f.typ=='C':
            b=('' if v is None else str(v)).encode('cp1252','replace')[:n]
            return b + b' '*(n-len(b))
        if f.typ in ('N','F'):
            if v is None or v=='': s=''
            elif f.decimals: s=f'{float(v):.{f.decimals}f}'
            else: s=str(int(v))
            if len(s)>n: raise ValueError(f'{f.name} value {s!r} exceeds width {n}')
            return s.rjust(n).encode('ascii')
        if f.typ=='L':
            return (b'T' if bool(v) else b'F') + b' '*(n-1)
        if f.typ=='D':
            s='' if v is None else str(v)
            return s[:n].ljust(n).encode('ascii','replace')
        b = bytes(v) if isinstance(v,(bytes,bytearray)) else b''
        return b[:n] + b'\x00'*(n-len(b))

    def write_records(self,out:Path,records:Iterable[Dict[str,Any]], production_mdx:bool=False):
        recs=list(records); hdr=bytearray(self.header)
        now=_dt.date.today(); hdr[1]=now.year-1900; hdr[2]=now.month; hdr[3]=now.day
        hdr[4:8]=len(recs).to_bytes(4,'little')
        # dBase production MDX flag at byte 28. Fresh DBFs default to no index.
        if len(hdr)>28: hdr[28]=1 if production_mdx else 0
        data=bytearray(hdr)
        for values in recs:
            r=bytearray(b' ')
            for f in self.fields: r.extend(self._format(f,values.get(f.name)))
            if len(r)!=self.record_len:
                raise AssertionError((self.path.name,len(r),self.record_len))
            data.extend(r)
        data.extend(b'\x1A')
        out.write_bytes(data)

    def active_records(self)->List[Dict[str,Any]]:
        out=[]
        for i in range(self.n_records):
            off=self.header_len+i*self.record_len; r=self.raw[off:off+self.record_len]
            if len(r)<self.record_len or r[:1]==b'*': continue
            pos=1; vals={}
            for f in self.fields:
                raw=bytes(r[pos:pos+f.length]); pos+=f.length
                s=raw.decode('cp1252','replace')
                if f.typ=='C': v=s.rstrip()
                elif f.typ in ('N','F'):
                    q=s.strip(); v=(float(q) if f.decimals else int(q)) if q else None
                elif f.typ=='L': v=s[:1].upper() in ('T','Y')
                else: v=s.strip()
                vals[f.name]=v
            out.append(vals)
        return out

# ---- dBASE IV production MDX rebuilding -----------------------------------
# DataTransit/BDE expects the production .MDX tags to exist (not merely the
# .MDX file itself).  Rewriting a DBF while leaving or removing its old MDX
# causes errors such as: "Index does not exist. Index: LST_ID."  The routines
# below rebuild the simple field indexes used by the Axion database skeleton.

@dataclass
class _MdxTreeNode:
    page: int
    max_key: bytes


def _mdx_numeric_key_from_ascii(raw: bytes, key_len: int = 12) -> bytes:
    """Encode a non-negative integer using the dBASE IV 12-byte MDX numeric key.

    All numeric production-index fields used by the Axion skeleton are
    zero-decimal, non-negative identifiers/ranks.  The encoding below was
    verified byte-for-byte against the original DataTransit MDX files for
    SEQINDEX, RANG, RES_ID, NUM_ID, CFG_ID, SYS_ID and EMPL_ID.
    """
    text = raw.decode('ascii', 'ignore').strip()
    if not text:
        # Axion's indexed ID/rank fields are populated.  Keep a deterministic
        # zero-like key for a blank should a template ever contain one.
        return bytes(key_len)
    if any(ch in text for ch in '.Ee'):
        value = float(text)
        if not value.is_integer() or value < 0:
            raise ValueError(f'Unsupported indexed numeric value {text!r}')
        text = str(int(value))
    else:
        value = int(text)
        if value < 0:
            raise ValueError(f'Unsupported negative indexed value {text!r}')
        text = str(value)
    if value == 0:
        key = bytearray((0x34, 0x01))
    else:
        digits = text
        nd = len(digits)
        key = bytearray((0x34 + nd, 0x01 + 4 * nd))
        for i in range(0, nd, 2):
            hi = ord(digits[i]) - 48
            lo = (ord(digits[i + 1]) - 48) if i + 1 < nd else 0
            key.append((hi << 4) | lo)
    return bytes(key[:key_len]).ljust(key_len, b'\x00')


def _dbf_index_entries(dbf_path: Path, expression: str, key_type: str,
                       key_len: int, item_len: int) -> List[Tuple[bytes, int]]:
    """Return (padded-key, physical-record-number) pairs for one MDX tag."""
    raw = dbf_path.read_bytes()
    if len(raw) < 33:
        raise ValueError(f'Invalid DBF: {dbf_path}')
    nrec = int.from_bytes(raw[4:8], 'little')
    hlen = int.from_bytes(raw[8:10], 'little')
    rlen = int.from_bytes(raw[10:12], 'little')
    wanted = expression.strip().upper()

    pos = 1
    field = None
    off = 32
    while off < hlen and raw[off] != 0x0D:
        d = raw[off:off + 32]
        name = d[:11].split(b'\x00', 1)[0].decode('latin1').upper()
        typ = chr(d[11]); length = d[16]; decimals = d[17]
        if name == wanted:
            field = (typ, length, decimals, pos)
        pos += length
        off += 32
    if field is None:
        raise ValueError(f'MDX expression {expression!r} is not a simple field in {dbf_path.name}')

    typ, flen, decimals, fpos = field
    key_area_len = item_len - 4
    entries: List[Tuple[bytes, int, Any]] = []
    for i in range(nrec):
        ro = hlen + i * rlen
        rec = raw[ro:ro + rlen]
        if len(rec) != rlen:
            raise ValueError(f'Truncated DBF record {i + 1} in {dbf_path.name}')
        fraw = rec[fpos:fpos + flen]
        recno = i + 1
        if key_type == 'C':
            k = fraw[:key_len].ljust(key_len, b' ')
            padded = k.ljust(key_area_len, b'\x00')[:key_area_len]
            sort_value: Any = k
        elif key_type == 'N':
            if decimals:
                raise ValueError(f'Indexed decimal field {wanted} is not supported')
            padded = _mdx_numeric_key_from_ascii(fraw, key_len).ljust(key_area_len, b'\x00')[:key_area_len]
            text = fraw.decode('ascii', 'ignore').strip()
            sort_value = int(text) if text else 0
        else:
            raise ValueError(f'Unsupported MDX key type {key_type!r} for {dbf_path.name}:{wanted}')
        # dBASE production indexes include physical records regardless of the
        # delete flag.  Our generated tables contain no deleted rows, but doing
        # the same thing makes the rebuilder faithful to the template.
        entries.append((padded, recno, sort_value))

    entries.sort(key=lambda x: (x[2], x[1]))
    return [(k, recno) for k, recno, _ in entries]


def _mdx_leaf_block(entries: List[Tuple[bytes, int]], item_len: int,
                    block_bytes: int) -> bytes:
    node = bytearray(block_bytes)
    struct.pack_into('<I', node, 0, len(entries))
    struct.pack_into('<I', node, 4, 0)
    for i, (key, recno) in enumerate(entries):
        o = 8 + i * item_len
        struct.pack_into('<I', node, o, recno)
        node[o + 4:o + item_len] = key[:item_len - 4].ljust(item_len - 4, b'\x00')
    return bytes(node)


def _mdx_branch_block(children: List[_MdxTreeNode], item_len: int,
                      block_bytes: int) -> bytes:
    """Create an MDX branch block.

    A branch with N children advertises N-1 comparison keys.  Child pointers
    occupy the same 4-byte slot used for record numbers in a leaf.  Each
    comparison key is the maximum key in that child; the final child's key is
    physically present but is not compared by the reader.
    """
    if len(children) < 2:
        raise ValueError('MDX branch requires at least two children')
    node = bytearray(block_bytes)
    struct.pack_into('<I', node, 0, len(children) - 1)
    # The legacy field at +4 is zero in leaves.  BDE also detects a branch from
    # the non-zero child pointer in slot [key_count], so zero is valid here.
    struct.pack_into('<I', node, 4, 0)
    for i, child in enumerate(children):
        o = 8 + i * item_len
        struct.pack_into('<I', node, o, child.page)
        node[o + 4:o + item_len] = child.max_key[:item_len - 4].ljust(item_len - 4, b'\x00')
    return bytes(node)


def _validate_mdx_tag(data: bytes, root_page: int, max_keys: int,
                      item_len: int) -> List[Tuple[bytes, int]]:
    """Walk a generated MDX tag and return its leaf entries in key order."""
    seen = set()
    def walk(page: int) -> List[Tuple[bytes, int]]:
        if page in seen:
            raise ValueError(f'MDX cycle at page {page}')
        seen.add(page)
        o = page * 512
        if o + 8 > len(data):
            raise ValueError(f'MDX node page {page} is outside the file')
        count = struct.unpack_from('<I', data, o)[0]
        if count > max_keys:
            raise ValueError(f'MDX node has {count} keys; maximum is {max_keys}')
        # Branch nodes have count+1 child slots; the last one is enough to
        # distinguish a branch from a leaf even when the legacy +4 value is 0.
        last_slot = o + 8 + count * item_len
        child_at_last = struct.unpack_from('<I', data, last_slot)[0] if last_slot + 4 <= len(data) else 0
        if child_at_last:
            result: List[Tuple[bytes, int]] = []
            for i in range(count + 1):
                so = o + 8 + i * item_len
                child = struct.unpack_from('<I', data, so)[0]
                if not child:
                    raise ValueError(f'MDX branch page {page} has a null child')
                result.extend(walk(child))
            return result
        result = []
        for i in range(count):
            so = o + 8 + i * item_len
            recno = struct.unpack_from('<I', data, so)[0]
            key = bytes(data[so + 4:so + item_len])
            result.append((key, recno))
        return result
    return walk(root_page)


def rebuild_production_mdx(dbf_path: Path, mdx_path: Path) -> Dict[str, int]:
    """Rebuild every simple-field tag in a DataTransit dBASE IV production MDX.

    The tag/header layout is retained from the known-good DataTransit template;
    only the B-tree nodes, per-tag pages-used count, and file end-page pointer
    are rebuilt.  This keeps DataTransit's expected tag names (LST_ID, RANG,
    etc.) while making their contents match the newly generated DBF records.
    """
    if not mdx_path.exists():
        raise FileNotFoundError(mdx_path)
    data = bytearray(mdx_path.read_bytes())
    if len(data) < 1024:
        raise ValueError(f'Invalid MDX: {mdx_path}')
    block_pages = int.from_bytes(data[20:22], 'little') or 2
    block_bytes = int.from_bytes(data[22:24], 'little') or (block_pages * 512)
    if block_bytes != block_pages * 512:
        raise ValueError(f'Unexpected MDX block sizing in {mdx_path.name}')
    if block_bytes < 512:
        raise ValueError(f'Invalid MDX block size in {mdx_path.name}')
    if len(data) % block_bytes:
        data.extend(b'\x00' * (block_bytes - len(data) % block_bytes))

    ntags = int.from_bytes(data[28:30], 'little')
    if not (0 < ntags <= 48):
        raise ValueError(f'Invalid MDX tag count {ntags} in {mdx_path.name}')

    def alloc(block: bytes) -> int:
        if len(block) != block_bytes:
            raise AssertionError('wrong MDX node size')
        if len(data) % block_bytes:
            raise AssertionError('unaligned MDX append')
        page = len(data) // 512
        data.extend(block)
        return page

    stats: Dict[str, int] = {}
    for ti in range(ntags):
        de = 544 + ti * 32
        if de + 32 > len(data):
            raise ValueError(f'Truncated MDX tag directory in {mdx_path.name}')
        tag_header_page = struct.unpack_from('<I', data, de)[0]
        ho = tag_header_page * 512
        if not tag_header_page or ho + 256 > len(data):
            raise ValueError(f'Bad MDX tag header page in {mdx_path.name}')
        root_page = struct.unpack_from('<I', data, ho)[0]
        key_type = chr(data[ho + 9])
        key_len = struct.unpack_from('<H', data, ho + 12)[0]
        max_keys = struct.unpack_from('<H', data, ho + 14)[0]
        item_len = struct.unpack_from('<H', data, ho + 18)[0]
        expression = bytes(data[ho + 24:ho + 125]).split(b'\x00', 1)[0].decode('latin1').strip()
        tag_name = bytes(data[de + 4:de + 15]).split(b'\x00', 1)[0].decode('latin1').strip() or expression
        if not root_page or max_keys < 2 or item_len < 8:
            raise ValueError(f'Unsupported MDX tag {tag_name!r} in {mdx_path.name}')

        entries = _dbf_index_entries(dbf_path, expression, key_type, key_len, item_len)
        nodes_used = 1
        root_off = root_page * 512
        if root_off + block_bytes > len(data):
            raise ValueError(f'MDX root page outside file for {tag_name}')

        if len(entries) <= max_keys:
            data[root_off:root_off + block_bytes] = _mdx_leaf_block(entries, item_len, block_bytes)
        else:
            children: List[_MdxTreeNode] = []
            for start in range(0, len(entries), max_keys):
                chunk = entries[start:start + max_keys]
                page = alloc(_mdx_leaf_block(chunk, item_len, block_bytes))
                children.append(_MdxTreeNode(page, chunk[-1][0]))
                nodes_used += 1

            while len(children) > max_keys:
                # Build a complete next level.  Distribute children evenly so
                # we never end up with a one-child branch (and never mix tree
                # depths by carrying a singleton upward).
                group_count = (len(children) + max_keys - 1) // max_keys
                base, extra = divmod(len(children), group_count)
                parents: List[_MdxTreeNode] = []
                at = 0
                for gi in range(group_count):
                    size = base + (1 if gi < extra else 0)
                    group = children[at:at + size]; at += size
                    if len(group) < 2 or len(group) > max_keys:
                        raise ValueError('Unable to balance MDX branch level')
                    page = alloc(_mdx_branch_block(group, item_len, block_bytes))
                    parents.append(_MdxTreeNode(page, group[-1].max_key))
                    nodes_used += 1
                children = parents

            if len(children) < 2:
                raise ValueError('Unexpected one-child MDX root')
            data[root_off:root_off + block_bytes] = _mdx_branch_block(children, item_len, block_bytes)

        # TagHeader.pagesused is measured in 512-byte pages.
        struct.pack_into('<I', data, ho + 4, nodes_used * block_pages)

        actual = _validate_mdx_tag(bytes(data), root_page, max_keys, item_len)
        if actual != entries:
            raise ValueError(f'Internal MDX validation failed for {mdx_path.name}:{tag_name}')
        stats[tag_name] = len(entries)

    # MDX anchor: nextAvailable / page number at end of file.
    struct.pack_into('<I', data, 32, len(data) // 512)
    # No free-list blocks are maintained by this compact rebuilder.
    struct.pack_into('<I', data, 36, 0)
    struct.pack_into('<I', data, 40, 0)
    mdx_path.write_bytes(data)

    # Mark the DBF as having a production MDX (dBASE header byte 28).
    dbf = bytearray(dbf_path.read_bytes())
    if len(dbf) > 28:
        dbf[28] = 1
        dbf_path.write_bytes(dbf)
    return stats

# ---- Axion PIC -------------------------------------------------------------
def image_to_axion_pic(img:Image.Image)->bytes:
    """Encode an Axion monochrome .PIC as bpc + column-major vertical bytes.

    Data is compatible with AIRPORT.PIC: byte 0 is bytes-per-column; each column
    stores 8-row chunks bottom-chunk first, with bit 0 at the top of each chunk.
    """
    if img.mode!='1':
        # exact color cannot be represented by monochrome .PIC
        img=img.convert('1')
    # DataTransit/Axion interprets the vertical origin opposite to the Luminator
    # raster renderer. Flip once during encoding so the pictogram appears upright.
    img = img.transpose(Image.Transpose.FLIP_TOP_BOTTOM)
    w,h=img.size
    bpc=(h+7)//8
    if not (1<=bpc<=255): raise ValueError('PIC height out of range')
    px=img.load(); out=bytearray([bpc])
    for x in range(w):
        col=[0]*bpc
        for y in range(h):
            if px[x,y]:
                chunk=y//8; stored=bpc-1-chunk
                col[stored] |= 1 << (y%8)
        out.extend(col)
    return bytes(out)

# ---- template inspection --------------------------------------------------
def _ci(root:Path,name:str)->Path:
    for p in root.iterdir():
        if p.name.lower()==name.lower(): return p
    raise FileNotFoundError(name)

def inspect_template(dbdir:Path):
    aff=DbfTemplate(_ci(dbdir,'Affichrs.DBF')).active_records()
    cfg=DbfTemplate(_ci(dbdir,'Configs.DBF')).active_records()
    aff_by={int(r['AFF_ID']):r for r in aff if r.get('AFF_ID') is not None}
    sources=[]
    for r in cfg:
        a=aff_by.get(int(r['AFF_ID']))
        if not a: continue
        sources.append(dict(src=int(r['SRC_ID']),cfg=int(r['CFG_ID']),aff=int(r['AFF_ID']),empl=int(r['EMPL_ID']),
                            w=int(a['DIMH']),h=int(a['DIMV']),type=a['TYPE'],name=a['AFF_NAME']))
    return sorted(sources,key=lambda r:r['src'])

def _extract_builtin_template(dst:Path)->Tuple[Path,Path]:
    """Extract the embedded known-good Axion database skeleton into *dst*."""
    with zipfile.ZipFile(io.BytesIO(_embedded_template_zip_bytes())) as zz:
        zz.extractall(dst)
    candidates=[]
    for p in dst.rglob('*'):
        if p.is_dir() and any(x.name.lower()=='parcours.dbf' for x in p.iterdir() if x.is_file()):
            candidates.append(p)
    if not candidates:
        raise ValueError('Embedded Axion skeleton is missing Parcours.DBF')
    dbdir=candidates[0]
    pic=dbdir.parent/'PICTOGRAM'
    if not pic.exists():
        found=[p for p in dst.rglob('*') if p.is_dir() and p.name.upper()=='PICTOGRAM']
        pic=found[0] if found else dbdir.parent/'PICTOGRAM'
    pic.mkdir(parents=True,exist_ok=True)
    if pic.name!='PICTOGRAM':
        new=pic.parent/'PICTOGRAM'; pic.rename(new); pic=new
    for old in list(pic.rglob('*')):
        if old.is_file(): old.unlink()
    return dbdir,pic

def image_to_axion_color_bmp(img:Image.Image, out:Path):
    """Write a DataTransit-compatible indexed 8-bit BMP preserving exact RGB colors."""
    rgb=img.convert('RGB')
    colors=rgb.getcolors(maxcolors=1000000)
    if colors is None:
        raise ValueError('Color pictogram has more than 255 colors')
    palette_colors=[]
    if (0,0,0) in [c for _,c in colors]: palette_colors.append((0,0,0))
    for _,c in sorted(colors, key=lambda x:x[1]):
        if c not in palette_colors: palette_colors.append(c)
    if len(palette_colors)>255:
        raise ValueError(f'Color pictogram has {len(palette_colors)} colors; Axion limit is 255')
    pal=Image.new('P',rgb.size)
    flat=[]
    for c in palette_colors: flat.extend(c)
    flat.extend([0]*(768-len(flat)))
    pal.putpalette(flat)
    lut={c:i for i,c in enumerate(palette_colors)}
    pixels = rgb.get_flattened_data() if hasattr(rgb, 'get_flattened_data') else rgb.getdata()
    pal.putdata([lut[p] for p in pixels])
    pal.save(out,format='BMP',bits=8)

def _image_is_multicolor(img:Image.Image)->bool:
    colors=img.convert('RGB').getcolors(maxcolors=1000000) or []
    nonblack={rgb for _,rgb in colors if rgb!=(0,0,0)}
    return len(nonblack)>1

def _alloc_addr(used:set[str])->str:
    # Existing color display definitions occupy C6/C7; continue upward first.
    for n in list(range(0xC8,0x100))+list(range(0x20,0xC8)):
        v=f'{n:02X}'
        if v not in used:
            used.add(v); return v
    return 'FF'

def ensure_axion_displays(dbdir:Path, sign_specs:List[Tuple[str,int,int,bool]]):
    """Ensure every Luminator matrix logical sign has an Axion source of equal dimensions.

    Known logical roles reuse the normal DataTransit placements (Front, Rear, Curb Side,
    Route Side). Every additional non-ODK logical sign consumes another available DataTransit
    placement. Existing AFFICHRS definitions are reused when suitable; otherwise an exact-size
    display definition is created automatically.
    """
    aff_tpl=DbfTemplate(_ci(dbdir,'Affichrs.DBF')); aff=aff_tpl.active_records()
    cfg_tpl=DbfTemplate(_ci(dbdir,'Configs.DBF')); cfg=cfg_tpl.active_records()
    emp=DbfTemplate(_ci(dbdir,'Emplacem.DBF')).active_records()
    emp_by_name={str(r.get('EMPL') or '').strip().upper():int(r['EMP_ID']) for r in emp if r.get('EMP_ID') is not None}
    cfg_by_empl={int(r['EMPL_ID']):r for r in cfg if r.get('EMPL_ID') is not None}
    used_src={int(r['SRC_ID']) for r in cfg if r.get('SRC_ID') is not None}
    used_addr={str(r.get('ADRIDENTIF') or '').upper() for r in aff}
    next_aff=max([int(r['AFF_ID']) for r in aff if r.get('AFF_ID') is not None] or [0])+1
    next_cfg=max([int(r['CFG_ID']) for r in cfg if r.get('CFG_ID') is not None] or [0])+1
    next_src=max(used_src or {0})+1

    role_names={
        'FRONT':'FRONT','REAR':'REAR','SIDE1':'CURB SIDE','SIDE2':'ROUTE SIDE',
    }
    # Every non-ODK logical sign gets its own Axion source. Prefer generic
    # placements for nonstandard signs, then use any still-free matrix placement.
    # Control Console is reserved for ODK text.
    fallback=[
        'AUXILIARY 1','AUXILIARY 2','NEXT STOP','PUBLIC INTEREST','KEY NUMBER',
        'FRONT','REAR','CURB SIDE','ROUTE SIDE',
    ]
    claimed=set()
    sign_to_src={}; created=[]; changed=[]

    aff_by_id={int(r['AFF_ID']):r for r in aff if r.get('AFF_ID') is not None}

    def choose_aff(w,h,is_color,preferred_id=None):
        nonlocal next_aff
        pref=aff_by_id.get(int(preferred_id)) if preferred_id is not None else None
        if pref and int(pref.get('DIMH') or 0)==w and int(pref.get('DIMV') or 0)==h and (not is_color or 'COLOR SIGN' in str(pref.get('AFF_NAME') or '').upper()):
            return int(pref['AFF_ID'])
        matches=[r for r in aff if int(r.get('DIMH') or 0)==w and int(r.get('DIMV') or 0)==h and str(r.get('TYPE') or '') in ('M','P','S')]
        if is_color:
            cm=[r for r in matches if 'COLOR SIGN' in str(r.get('AFF_NAME') or '').upper()]
            if cm: return int(cm[0]['AFF_ID'])
            # For color signs create a color-specific display even if a monochrome size exists.
        elif matches:
            mono=[r for r in matches if 'COLOR SIGN' not in str(r.get('AFF_NAME') or '').upper()]
            return int((mono or matches)[0]['AFF_ID'])
        rec=dict(AFF_ID=next_aff,TYPE='M',DIMH=w,DIMV=h,ADRIDENTIF=_alloc_addr(used_addr),
                 AFF_NAME=(f'Color Sign {h}x{w}' if is_color else f'Auto Matrix {h}x{w}')[:30],
                 LED_WARN=101,NOPATTERN=None,COLOREND=None)
        aff.append(rec); aff_by_id[int(rec['AFF_ID'])]=rec; created.append(rec.copy()); next_aff+=1
        return int(rec['AFF_ID'])

    ordered=sorted(sign_specs,key=lambda x:(0 if x[0].upper()=='FRONT' else 1 if x[0].upper()=='REAR' else 2 if x[0].upper().startswith('SIDE') else 3,x[0]))
    for name,w,h,is_color in ordered:
        up=name.upper()
        place=role_names.get(up)
        if place and place in claimed: place=None
        if not place:
            place=next((x for x in fallback if x not in claimed and x in emp_by_name),None)
        if not place:
            raise ValueError(f'No free Axion display placement is available for logical sign {name} ({w}x{h})')
        claimed.add(place); empl_id=emp_by_name[place]
        current=cfg_by_empl.get(empl_id)
        aff_id=choose_aff(w,h,is_color,current.get('AFF_ID') if current else None)
        if empl_id in cfg_by_empl:
            r=cfg_by_empl[empl_id]
            old=int(r.get('AFF_ID') or 0); r['AFF_ID']=aff_id
            src=int(r['SRC_ID'])
            if old!=aff_id: changed.append((name,src,old,aff_id,w,h,is_color))
        else:
            while next_src in used_src: next_src+=1
            r=dict(CFG_ID=next_cfg,SYS_ID=1,AFF_ID=aff_id,EMPL_ID=empl_id,SRC_ID=next_src,GAUCHE=10,TOP=10,LED='')
            cfg.append(r); cfg_by_empl[empl_id]=r; used_src.add(next_src)
            src=next_src; next_src+=1; next_cfg+=1
            changed.append((name,src,None,aff_id,w,h,is_color))
        sign_to_src[name]=src

    aff_tpl.write_records(_ci(dbdir,'Affichrs.DBF'),aff, production_mdx=True)
    cfg_tpl.write_records(_ci(dbdir,'Configs.DBF'),cfg, production_mdx=True)
    return sign_to_src,created,changed

# ---- conversion -----------------------------------------------------------
def convert(ips:Path, out_zip:Path, *, msg_class:int=3, seconds:int=2,
            index_mode:str='rebuild', progress_callback=None)->Dict[str,Any]:
    def _progress(value, message=''):
        if progress_callback:
            try:
                progress_callback(max(0.0, min(100.0, float(value))), message)
            except Exception:
                pass

    _progress(0, 'Loading converter…')
    core=_load_renderer()
    temp=Path(tempfile.mkdtemp(prefix='lum2axion_'))
    try:
        _progress(2, 'Extracting embedded Axion database…')
        dbdir,picdir=_extract_builtin_template(temp)

        # Render first so the Axion configuration can be adapted to the actual IPS.
        rend=temp/'_rendered'
        def _renderer_progress(value, message=''):
            _progress(3 + (float(value) * 0.42), message or 'Rendering Luminator signs…')
        try:
            core.build_export(ips,rend,all_frames=True,scale=1,export_excel=False,progress_callback=_renderer_progress,dedupe_same_size=False)
        except TypeError as exc:
            # Older renderer revisions deduplicated identical same-size logical
            # signs.  That is unsafe for conversion because SIDE1/SIDE2 are
            # separate physical outputs.  Require the matching updated renderer.
            if 'dedupe_same_size' in str(exc):
                raise RuntimeError(
                    'This converter requires the updated luminator_ips_export.py '
                    'with per-logical-sign rendering support. Keep both updated '
                    'files in the same folder.'
                ) from exc
            if 'progress_callback' not in str(exc):
                raise
            _progress(4, 'Rendering Luminator signs…')
            core.build_export(ips,rend,all_frames=True,scale=1,export_excel=False,dedupe_same_size=False)
        _progress(45, 'Reading rendered sign manifest…')
        with (rend/'manifest.tsv').open(encoding='utf-8') as f:
            manifest=list(csv.DictReader(f,delimiter='\t'))

        # Determine matrix logical signs and whether each one really needs color.
        sign_dims={}
        sign_color={}
        manifest_total=max(1,len(manifest))
        for manifest_i,row in enumerate(manifest,start=1):
            if manifest_i == 1 or manifest_i == manifest_total or manifest_i % max(1,manifest_total//50) == 0:
                _progress(45 + 4*(manifest_i/manifest_total), f'Analyzing sign {manifest_i:,} of {manifest_total:,}…')
            if int(row['msg_class'])!=msg_class: continue
            n=row['logical_sign']; w=int(row['width']); h=int(row['height'])
            if n.upper()=='ODK': continue
            sign_dims[n]=(w,h)
            if not sign_color.get(n,False):
                with Image.open(rend/row['relative_path']) as im:
                    sign_color[n]=_image_is_multicolor(im)
        sign_specs=[(n,w,h,bool(sign_color.get(n))) for n,(w,h) in sign_dims.items()]
        _progress(50, 'Creating matching Axion display definitions…')
        sign_to_src,created_aff,changed_cfg=ensure_axion_displays(dbdir,sign_specs)
        sources=inspect_template(dbdir)
        src_by_id={s['src']:s for s in sources}

        # Index every rendered exposure directly by its logical-sign source.
        selected={}
        _progress(52, 'Indexing rendered exposures…')
        for row in manifest:
            if int(row['msg_class'])!=msg_class: continue
            n=row['logical_sign']
            if n not in sign_to_src: continue
            src=sign_to_src[n]; code=int(row['msg_code']); exp=int(row['exposure'])
            p=rend/row['relative_path']
            with Image.open(p) as im:
                selected[(code,src,exp)]=(row,im.copy(),src_by_id[src])

        _progress(54, 'Converting ODK text to Control Console messages…')
        # Control Console from ODK, 20 chars maximum.
        odk_rows=[]
        try:
            src_db=core.Jet3Reader(ips)
            sign_td=src_db.find_table('LSignID','LSignName','LSignDotHeight','LSignDotWidth')
            msg_td=src_db.find_table('MsgFrameID','MsgCode','LSignID','Phrase','FontID','XPos','YPos','Frame')
            odk_ids={r['LSignID'] for r in src_db.rows(sign_td) if str(r.get('LSignName') or '').upper()=='ODK'}
            odk_groups={}
            for r in src_db.rows(msg_td):
                if int(r.get('MsgClassID') or 0)!=msg_class or r.get('LSignID') not in odk_ids: continue
                code=r.get('MsgCode'); frame=r.get('Frame')
                if code is None or frame is None: continue
                phrase=str(r.get('Phrase') or '').strip()
                if phrase: odk_groups.setdefault((int(code),int(frame)),[]).append(r)
            by_code={}
            for (code,frame),parts in odk_groups.items():
                parts=sorted(parts,key=lambda r:((r.get('YPos') or 1),(r.get('XPos') or 1),(r.get('MsgFrameID') or 0)))
                text=' '.join(str(r.get('Phrase') or '').strip() for r in parts if str(r.get('Phrase') or '').strip())
                text=' '.join(text.split())[:20]
                if text: by_code.setdefault(code,[]).append((frame,text))
            for code,items in by_code.items():
                for rank,(frame,text) in enumerate(sorted(items,key=lambda x:x[0]),start=1):
                    odk_rows.append(dict(RANG=rank,LST_ID=f'R1P{code}S4',TEMPS=seconds,CENTRE=False,MESSAGE=text))
        except (KeyError,ValueError):
            odk_rows=[]

        _progress(57, 'Preparing Axion route codes…')
        codes=sorted(set(k[0] for k in selected) | {int(r['LST_ID'].split('P',1)[1].split('S',1)[0]) for r in odk_rows})
        parcours_tpl=DbfTemplate(_ci(dbdir,'Parcours.DBF'))
        prcr_field=next(f for f in parcours_tpl.fields if f.name=='PRCR_ID')
        unrepresentable=[c for c in codes if len(str(c))>prcr_field.length]
        codes=[c for c in codes if c not in unrepresentable]; allowed_codes=set(codes)
        odk_rows=[r for r in odk_rows if int(r['LST_ID'].split('P',1)[1].split('S',1)[0]) in allowed_codes]

        msg_rows=[]; seq_rows=[]; pic_count=0; color_count=0; mono_count=0
        total_pics=sum(1 for (code,src,exp) in selected if code in allowed_codes)
        done_pics=0
        _progress(60, f'Generating {total_pics:,} Axion pictograms…')
        for code in codes:
            for src in sorted(src_by_id):
                exps=sorted(k[2] for k in selected if k[0]==code and k[1]==src)
                if not exps: continue
                lst=f'R1P{code}S{src}'
                for seq_idx,exp in enumerate(exps):
                    row,img,_=selected[(code,src,exp)]
                    is_color=bool(sign_color.get(row['logical_sign'],False))
                    if is_color:
                        # DataTransit stores color-sign pictograms in a dedicated
                        # subdirectory and browses only *.bmp there.  The MSG field
                        # still contains just the filename; the active color-sign
                        # display determines which pictogram directory is used.
                        fn=f'{code}_{src}_{exp:02d}.BMP'
                        color_picdir=picdir/'ColorSignPictogram'
                        color_picdir.mkdir(parents=True,exist_ok=True)
                        image_to_axion_color_bmp(img,color_picdir/fn); color_count+=1
                    else:
                        fn=f'{code}_{src}_{exp:02d}.PIC'
                        (picdir/fn).write_bytes(image_to_axion_pic(img.convert('1'))); mono_count+=1
                    pic_count+=1
                    # DataTransit distinguishes ordinary .PIC pictograms from color-sign
                    # BMP pictograms through ITEMTYPE.  ITEMTYPE='1' makes the loader look
                    # directly under REPPICTOGR; ITEMTYPE='2' makes it prepend
                    # 'ColorSignPictogram\\'.  Using '1' for a BMP therefore produces
                    # "Impossible to find ...BMP" even when the file is present in the
                    # color pictogram folder.
                    msg_rows.append(dict(LST_ID=lst,RANG=exp,MSG=fn,TAILLEFONT='0',NOLIGNE=0,
                                         COLDEBUT=1,IMAGEACTIV=True,CENTRER=False,_DBASELOCK='',LINEPIXEL=0,
                                         ITEMTYPE=('2' if is_color else '1'),COULITEM=None,COULOUTLIN=None,BOTTOMLINE=None,RIGHTCOLON=None))
                    seq_rows.append(dict(LST_ID=lst,SEQINDEX=seq_idx,ACTION='D',PARAM1=exp,_DBASELOCK='',
                                         PARAM2=seconds,INVERSE=False,BLINK=False,NUMDISPLAY=exp,
                                         PARAM3=0,EFFECTZONE=None,PARAM4=None,PARAM5=None))
                    done_pics += 1
                    if done_pics == 1 or done_pics == total_pics or done_pics % max(1,total_pics//200) == 0:
                        _progress(60 + 28*(done_pics/max(1,total_pics)), f'Generating pictogram {done_pics:,} of {total_pics:,}…')

        _progress(89, 'Writing Axion database tables…')
        parcours=[dict(PRCR_ID=str(c),RES_ID=1,DEPENDANT=True,NUM_ID=c,LETTRE='',ALLOWRTNUM=False) for c in codes]
        parcours_tpl.write_records(_ci(dbdir,'Parcours.DBF'),parcours, production_mdx=True)
        DbfTemplate(_ci(dbdir,'Msgmatri.DBF')).write_records(_ci(dbdir,'Msgmatri.DBF'),msg_rows, production_mdx=True)
        DbfTemplate(_ci(dbdir,'Sequence.DBF')).write_records(_ci(dbdir,'Sequence.DBF'),seq_rows, production_mdx=True)
        try: DbfTemplate(_ci(dbdir,'Msghect.DBF')).write_records(_ci(dbdir,'Msghect.DBF'),odk_rows, production_mdx=True)
        except FileNotFoundError: pass

        _progress(92, 'Rebuilding DataTransit production indexes…')
        modified=['Parcours','Msgmatri','Sequence','Msghect','Configs','Affichrs']
        rebuilt_indexes={}
        for ix_i, stem in enumerate(modified, start=1):
            try:
                dbf_path=_ci(dbdir,stem+'.DBF')
                mdx_path=_ci(dbdir,stem+'.MDX')
            except FileNotFoundError:
                continue
            rebuilt_indexes[stem]=rebuild_production_mdx(dbf_path,mdx_path)
            _progress(92 + 2.0*(ix_i/len(modified)), f'Rebuilding index {ix_i} of {len(modified)}: {stem}…')
        index_mode='rebuild'

        _progress(94, 'Writing conversion report…')
        report=dbdir.parent/'CONVERSION_REPORT.txt'
        report.write_text(
            'Luminator -> Axion conversion\n'
            f'Source IPS: {ips.name}\nTemplate: embedded Axion/DataTransit skeleton\nMessage class: {msg_class}\nExposure seconds: {seconds}\n\n'
            'Logical sign -> Axion source mapping:\n' + ''.join(
                f'  {n}: {sign_dims[n][0]}x{sign_dims[n][1]} -> S{src} ({src_by_id[src]["name"]})\n' for n,src in sorted(sign_to_src.items())) +
            f'\nAxion route codes written: {len(codes)}\nPictograms written: {pic_count}\nMonochrome PIC: {mono_count}\nColor BMP: {color_count}\n'
            f'MSGMATRI rows: {len(msg_rows)}\nSEQUENCE rows: {len(seq_rows)}\nControl Console rows: {len(odk_rows)}\nColor pictogram folder: PICTOGRAM\\ColorSignPictogram\\\n'
            f'Codes exceeding PRCR_ID width and skipped: {unrepresentable}\n'
            f'New AFFICHRS display definitions: {len(created_aff)}\nChanged/added CONFIGS entries: {len(changed_cfg)}\n\n'
            'INDEX NOTE:\nProduction MDX indexes were rebuilt to match the generated DBF records (including LST_ID/RANG/SEQINDEX tags).\n',
            encoding='utf-8')

        shutil.rmtree(rend,ignore_errors=True)
        out_zip.parent.mkdir(parents=True,exist_ok=True)
        zip_files=[p for p in sorted(temp.rglob('*')) if p.is_file()]
        zip_total=max(1,len(zip_files))
        _progress(96, f'Packaging {len(zip_files):,} files into ZIP…')
        with zipfile.ZipFile(out_zip,'w',zipfile.ZIP_DEFLATED) as z:
            for zip_i,p in enumerate(zip_files,start=1):
                z.write(p,p.relative_to(temp))
                if zip_i == 1 or zip_i == zip_total or zip_i % max(1,zip_total//100) == 0:
                    _progress(96 + 4*(zip_i/zip_total), f'Packaging file {zip_i:,} of {zip_total:,}…')
        _progress(100, 'Conversion complete')
        return dict(codes=len(codes),pictograms=pic_count,mono_pictograms=mono_count,color_pictograms=color_count,
                    msg_rows=len(msg_rows),seq_rows=len(seq_rows),console_rows=len(odk_rows),unrepresentable=unrepresentable,
                    sources=sources,sign_to_src=sign_to_src,created_displays=created_aff,changed_configs=changed_cfg,
                    unmapped=[],index_mode='rebuild',rebuilt_indexes=rebuilt_indexes)
    finally:
        shutil.rmtree(temp,ignore_errors=True)

def _suggest_output_path(ips: Path) -> Path:
    try:
        return ips.with_name(f'{ips.stem}_to_Axion.zip')
    except Exception:
        return Path.cwd() / 'Axion_conversion.zip'


def launch_gui(initial_ips: Optional[Path]=None):
    """Small Tkinter front-end. The Axion skeleton is built into this program."""
    import threading
    import traceback
    import tkinter as tk
    from tkinter import filedialog, messagebox, ttk

    root=tk.Tk()
    root.title('Luminator IPS → Axion Converter')
    root.geometry('760x525')
    root.minsize(680,480)

    pad={'padx':10,'pady':6}
    outer=ttk.Frame(root,padding=14)
    outer.pack(fill='both',expand=True)
    outer.columnconfigure(1,weight=1)

    ips_var=tk.StringVar(value=str(initial_ips or ''))
    out_var=tk.StringVar(value=str(_suggest_output_path(initial_ips)) if initial_ips else '')
    cls_var=tk.IntVar(value=3)
    sec_var=tk.IntVar(value=2)
    status_var=tk.StringVar(value='Ready')
    progress_var=tk.DoubleVar(value=0.0)
    percent_var=tk.StringVar(value='0%')

    def choose_ips():
        fn=filedialog.askopenfilename(title='Select Luminator IPS database',filetypes=[('Luminator IPS','*.ips'),('All files','*.*')])
        if fn:
            ips_var.set(fn)
            if not out_var.get().strip(): out_var.set(str(_suggest_output_path(Path(fn))))

    def choose_output():
        initial='Axion_conversion.zip'
        if ips_var.get().strip(): initial=f'{Path(ips_var.get()).stem}_to_Axion.zip'
        fn=filedialog.asksaveasfilename(title='Save converted Axion database',defaultextension='.zip',initialfile=initial,filetypes=[('ZIP archive','*.zip')])
        if fn: out_var.set(fn)

    ttk.Label(outer,text='Luminator IPS → Axion Converter',font=('TkDefaultFont',14,'bold')).grid(row=0,column=0,columnspan=3,sticky='w',pady=(0,12))
    ttk.Label(outer,text='Luminator IPS').grid(row=1,column=0,sticky='w',**pad)
    ttk.Entry(outer,textvariable=ips_var).grid(row=1,column=1,sticky='ew',**pad)
    ttk.Button(outer,text='Browse…',command=choose_ips).grid(row=1,column=2,**pad)

    ttk.Label(outer,text='Output ZIP').grid(row=2,column=0,sticky='w',**pad)
    ttk.Entry(outer,textvariable=out_var).grid(row=2,column=1,sticky='ew',**pad)
    ttk.Button(outer,text='Browse…',command=choose_output).grid(row=2,column=2,**pad)

    opts=ttk.LabelFrame(outer,text='Conversion options',padding=10)
    opts.grid(row=3,column=0,columnspan=3,sticky='ew',padx=10,pady=(10,8))
    for c in range(4): opts.columnconfigure(c,weight=1 if c in (1,3) else 0)
    ttk.Label(opts,text='Message class').grid(row=0,column=0,sticky='w',padx=6,pady=5)
    ttk.Spinbox(opts,from_=1,to=99,textvariable=cls_var,width=8).grid(row=0,column=1,sticky='w',padx=6,pady=5)
    ttk.Label(opts,text='Exposure seconds').grid(row=0,column=2,sticky='w',padx=6,pady=5)
    ttk.Spinbox(opts,from_=1,to=99,textvariable=sec_var,width=8).grid(row=0,column=3,sticky='w',padx=6,pady=5)

    note=ttk.Label(outer,text='Axion template is built in. Every non-ODK logical sign is converted as its own display source and exact sign sizes are created/reused automatically. ODK becomes 20-character Control Console text. Monochrome signs use PICTOGRAM\\*.PIC; multi-color signs use indexed BMPs in PICTOGRAM\\ColorSignPictogram\\.',wraplength=700,foreground='#555555')
    note.grid(row=4,column=0,columnspan=3,sticky='w',padx=10,pady=(0,8))

    log=tk.Text(outer,height=13,wrap='word',state='disabled')
    log.grid(row=5,column=0,columnspan=3,sticky='nsew',padx=10,pady=8)
    outer.rowconfigure(5,weight=1)
    sb=ttk.Scrollbar(outer,orient='vertical',command=log.yview)
    sb.grid(row=5,column=3,sticky='ns',pady=8)
    log.configure(yscrollcommand=sb.set)

    def append(msg):
        log.configure(state='normal'); log.insert('end',msg.rstrip()+'\n'); log.see('end'); log.configure(state='disabled')

    prog=ttk.Progressbar(outer,mode='determinate',maximum=100.0,variable=progress_var)
    prog.grid(row=6,column=0,columnspan=2,sticky='ew',padx=10,pady=6)
    progress_status=ttk.Frame(outer)
    progress_status.grid(row=6,column=2,sticky='e',padx=10,pady=6)
    ttk.Label(progress_status,textvariable=percent_var,width=5,anchor='e').pack(side='left',padx=(0,8))
    ttk.Label(progress_status,textvariable=status_var).pack(side='left')
    buttons=ttk.Frame(outer); buttons.grid(row=7,column=0,columnspan=3,sticky='e',padx=10,pady=(4,0))
    run_btn=ttk.Button(buttons,text='Convert'); run_btn.pack(side='left',padx=5)
    ttk.Button(buttons,text='Close',command=root.destroy).pack(side='left',padx=5)

    def finish_ok(stats,out):
        progress_var.set(100.0); percent_var.set('100%'); run_btn.configure(state='normal'); status_var.set('Complete')
        append(''); append(f'Complete: {out}')
        append(f"Codes: {stats['codes']}   Pictograms: {stats['pictograms']}   MSGMATRI: {stats['msg_rows']}   SEQUENCE: {stats['seq_rows']}   Console: {stats.get('console_rows',0)}")
        if stats.get('unrepresentable'): append(f"Skipped codes too long for PRCR_ID: {stats['unrepresentable']}")
        append(f"Monochrome PIC: {stats.get('mono_pictograms',0)}   Color BMP: {stats.get('color_pictograms',0)}")
        if stats.get('created_displays'): append(f"New Axion display definitions: {len(stats['created_displays'])}")
        if stats.get('changed_configs'): append(f"Display configurations changed/added: {len(stats['changed_configs'])}")
        messagebox.showinfo('Conversion complete',f'Created:\n{out}\n\nPictograms: {stats["pictograms"]}\nRoute codes: {stats["codes"]}')

    def finish_err(text):
        run_btn.configure(state='normal'); status_var.set('Failed'); append(text)
        messagebox.showerror('Conversion failed',text.splitlines()[-1] if text else 'Unknown error')

    def do_convert():
        try:
            ips=Path(ips_var.get().strip()); out=Path(out_var.get().strip())
            if not ips.is_file(): raise ValueError('Select a valid Luminator .ips file.')
            if not out.name: raise ValueError('Choose an output ZIP path.')
            if out.suffix.lower()!='.zip': out=out.with_suffix('.zip'); out_var.set(str(out))
            mc=int(cls_var.get()); secs=int(sec_var.get())
            if secs<1: raise ValueError('Exposure seconds must be at least 1.')
        except Exception as e:
            messagebox.showerror('Invalid settings',str(e)); return
        run_btn.configure(state='disabled'); progress_var.set(0.0); percent_var.set('0%'); status_var.set('Starting…')
        append(f'IPS: {ips}'); append('Axion template: embedded')
        append(f'Output: {out}')
        append(f'Options: class={mc}, seconds={secs}, indexes=rebuild')
        append('Rendering signs and building Axion database…')
        def gui_progress(value,message=''):
            value=max(0.0,min(100.0,float(value)))
            def apply():
                progress_var.set(value)
                percent_var.set(f'{int(round(value))}%')
                if message:
                    status_var.set(message)
            root.after(0,apply)

        def worker():
            try:
                st=convert(ips,out,msg_class=mc,seconds=secs,index_mode='rebuild',progress_callback=gui_progress)
                root.after(0,lambda:finish_ok(st,out))
            except Exception:
                t=traceback.format_exc(); root.after(0,lambda:finish_err(t))
        threading.Thread(target=worker,daemon=True).start()

    run_btn.configure(command=do_convert)
    root.mainloop()


def main(argv=None):
    argv=list(sys.argv[1:] if argv is None else argv)
    if not argv or argv==['--gui']:
        launch_gui(); return 0
    if '--gui' in argv:
        args=[a for a in argv if a!='--gui']
        ips=Path(args[0]) if args else None
        launch_gui(ips); return 0

    ap=argparse.ArgumentParser(description='Convert a Luminator IPS to an Axion/DataTransit database using the built-in template')
    ap.add_argument('ips',type=Path)
    ap.add_argument('-o','--output',type=Path,required=True)
    ap.add_argument('--message-class',type=int,default=3)
    ap.add_argument('--seconds',type=int,default=2)
    ap.add_argument('--side',choices=['SIDE1','SIDE2'],help=argparse.SUPPRESS)  # legacy; all logical signs are converted
    ap.add_argument('--index-mode',choices=['rebuild','remove','preserve'],default='rebuild',help=argparse.SUPPRESS)
    a=ap.parse_args(argv)
    st=convert(a.ips,a.output,msg_class=a.message_class,seconds=a.seconds,index_mode=a.index_mode)
    print('Converted:',st)
    return 0

if __name__=='__main__':
    raise SystemExit(main())
